#[cfg(test)]
mod tests {
    #[test]
    fn root_warning_escalation_rejects_a_real_cargo_warning() {
        use std::process::Command;
        use std::time::{SystemTime, UNIX_EPOCH};

        let unique = SystemTime::now()
            .duration_since(UNIX_EPOCH)
            .expect("system clock must be after UNIX_EPOCH")
            .as_nanos();
        let probe_root = std::env::temp_dir().join(format!(
            "etuschlopf_warning_probe_{}_{}",
            std::process::id(),
            unique
        ));
        let src_dir = probe_root.join("src");
        std::fs::create_dir_all(&src_dir).expect("warning probe src directory must be creatable");
        std::fs::write(
            probe_root.join("Cargo.toml"),
            "[package]\nname = \"etuschlopf-warning-probe\"\nversion = \"0.0.0\"\nedition = \"2024\"\n\n[lints.rust]\nwarnings = \"deny\"\n",
        )
        .expect("warning probe Cargo.toml must be writable");
        std::fs::write(
            src_dir.join("lib.rs"),
            "pub fn warning_probe() { let deliberately_unused = 1_u8; }\n",
        )
        .expect("warning probe source must be writable");

        let cargo = std::env::var_os("CARGO").unwrap_or_else(|| "cargo".into());
        let output = Command::new(cargo)
            .arg("check")
            .arg("--quiet")
            .arg("--manifest-path")
            .arg(probe_root.join("Cargo.toml"))
            .arg("--target-dir")
            .arg(probe_root.join("target"))
            .output()
            .expect("cargo must execute the warning probe");
        let stderr = String::from_utf8_lossy(&output.stderr);
        let warning_is_the_failure =
            stderr.contains("unused variable") || stderr.contains("unused_variables");

        let _ = std::fs::remove_dir_all(&probe_root);

        assert!(
            !output.status.success(),
            "real Cargo warning probe unexpectedly succeeded"
        );
        assert!(
            warning_is_the_failure,
            "Cargo probe failed, but not because the deliberate unused-variable warning was denied: {stderr}"
        );
    }
}


